class Solution:
    def smallerToTheRight(self, nums: List[int]) -> List[int]:
        res = [0] * len(nums)

        def sort(idx):
            if len(idx) < 2:
                return idx
            mid = len(idx) // 2
            left, right = sort(idx[:mid]), sort(idx[mid:])
            out, j = [], 0
            for i in left:
                # right elements strictly smaller than nums[i] jump ahead of it
                while j < len(right) and nums[right[j]] < nums[i]:
                    out.append(right[j])
                    j += 1
                res[i] += j
                out.append(i)
            out.extend(right[j:])
            return out

        sort(list(range(len(nums))))
        return res

