  const n = nums.length, res = new Array(n).fill(0);
  let idx = nums.map((_, i) => i);
  const buf = new Array(n);
  const sort = (lo, hi) => {
    if (hi - lo < 2) return;
    const mid = lo + hi >> 1;
    sort(lo, mid);
    sort(mid, hi);
    let i = lo, j = mid, k = lo;
    while (i < mid || j < hi) {
      if (j < hi && (i >= mid || nums[idx[j]] < nums[idx[i]])) buf[k++] = idx[j++];
      else {
        res[idx[i]] += j - mid;
        buf[k++] = idx[i++];
      }
    }
    for (let t = lo; t < hi; t++) idx[t] = buf[t];
  };
  sort(0, n);
  return res;
}
